@startuml

class Person {
  + firstName : string
  + lastName : string
  + birthDate : date
}

class Trainer {
  + diploma : string
}

class FitnessCenter {
  + name : string
  + address : string
}

class Room {
  + number : int
  + capacity : int
}

abstract class Session {
  + startDate : date
  + startHour : time
}

class GroupSession extends Session {
  + type : string
  + trainer : Trainer
}

class IndividualSession extends Session {}

class Participant {
  + person : Person
}

class Member {
  + person : Person
}

class ProspectiveMember {
  + person : Person
}

class InternTrainer {
  + person : Person
}

FitnessCenter "1" *-- "*" Room
Room "0..*" -- "1..*" GroupSession
Room "0..*" -- "0..*" IndividualSession
Person "1" -- "*" Participant
Person "1" -- "*" Member
Person "1" -- "*" ProspectiveMember
Person "1" -- "*" InternTrainer
GroupSession "1" -- "1" Trainer
IndividualSession "0..1" -- "1" Trainer

@enduml

